using System.Net;using System.Net.Http.Json;using System.Text.Json;using System.Text.Json.Serialization;using LigaVolley.Application.MatchSheets;using LigaVolley.Domain.CompetitionFormats;using LigaVolley.Domain.CompetitionRosters;using LigaVolley.Domain.Competitions;using LigaVolley.Domain.Divisions;using LigaVolley.Domain.Fixtures;using LigaVolley.Domain.MatchOfficials;using LigaVolley.Domain.People;using LigaVolley.Domain.Seasons;using LigaVolley.Domain.TeamEntries;using LigaVolley.Domain.Teams;using LigaVolley.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;
namespace LigaVolley.IntegrationTests;
public sealed class MatchSheetOpeningEndpointsTests(LigaVolleyApiFactory factory):IClassFixture<LigaVolleyApiFactory>
{
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web){Converters={new JsonStringEnumConverter()}};
 [Fact]public async Task Context_open_retry_and_persisted_snapshot_are_consistent(){var x=await Seed();var context=await factory.Client.GetFromJsonAsync<OpenMatchContextDto>($"/api/scorer/matches/{x.MatchId}/open-context",Json);Assert.NotNull(context);Assert.Equal(6,context.Home.Players.Count);Assert.Equal(3,context.MatchOfficials.Count);Assert.Null(context.ExistingMatchSheet);var request=Request(x);var first=await factory.Client.PostAsJsonAsync($"/api/scorer/matches/{x.MatchId}/open",request,Json);Assert.Equal(HttpStatusCode.Created,first.StatusCode);var opened=(await first.Content.ReadFromJsonAsync<OpenMatchSheetResponse>(Json))!;Assert.False(opened.AlreadyOpen);Assert.Equal(6,opened.MatchSheet.Home.Players.Count);Assert.Null(opened.MatchSheet.CurrentState.CurrentSetNumber);Assert.Equal((byte)0,opened.MatchSheet.CurrentState.HomeSets);var retry=await factory.Client.PostAsJsonAsync($"/api/scorer/matches/{x.MatchId}/open",request with{DeviceId="ignored-on-retry"},Json);Assert.Equal(HttpStatusCode.OK,retry.StatusCode);var retried=(await retry.Content.ReadFromJsonAsync<OpenMatchSheetResponse>(Json))!;Assert.True(retried.AlreadyOpen);Assert.Equal(opened.MatchSheet.Sheet.SheetUuid,retried.MatchSheet.Sheet.SheetUuid);var sheet=await factory.Client.GetFromJsonAsync<MatchSheetSnapshotDto>($"/api/scorer/matches/{x.MatchId}/sheet",Json);Assert.Equal(opened.MatchSheet.Sheet.SheetUuid,sheet!.Sheet.SheetUuid);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<LigaVolleyDbContext>();Assert.Equal(1,await db.MatchSheets.CountAsync(s=>s.MatchId==x.MatchId));}
 [Fact]public async Task Open_validates_minimum_players_and_is_atomic(){var x=await Seed();var q=Request(x);q=q with{Home=q.Home with{CompetitionRosterPlayerIds=q.Home.CompetitionRosterPlayerIds.Take(5).ToArray()}};var response=await factory.Client.PostAsJsonAsync($"/api/scorer/matches/{x.MatchId}/open",q,Json);Assert.Equal(HttpStatusCode.BadRequest,response.StatusCode);Assert.Equal("match_requires_six_players",(await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("code").GetString());await using var scope=factory.Services.CreateAsyncScope();Assert.False(await scope.ServiceProvider.GetRequiredService<LigaVolleyDbContext>().MatchSheets.AnyAsync(s=>s.MatchId==x.MatchId));}
 [Fact]public async Task Concurrent_open_creates_one_sheet_and_two_consistent_responses(){var x=await Seed();var q=Request(x);var responses=await Task.WhenAll(factory.Client.PostAsJsonAsync($"/api/scorer/matches/{x.MatchId}/open",q,Json),factory.Client.PostAsJsonAsync($"/api/scorer/matches/{x.MatchId}/open",q,Json));Assert.All(responses,r=>Assert.Contains(r.StatusCode,new[]{HttpStatusCode.Created,HttpStatusCode.OK}));var bodies=await Task.WhenAll(responses.Select(r=>r.Content.ReadFromJsonAsync<OpenMatchSheetResponse>(Json)));Assert.Single(bodies.Select(b=>b!.MatchSheet.Sheet.SheetUuid).Distinct());}
 [Fact]public async Task OpenApi_documents_open_context_open_and_sheet(){var json=await factory.Client.GetStringAsync("/swagger/v1/swagger.json");using var doc=JsonDocument.Parse(json);var p=doc.RootElement.GetProperty("paths");Assert.True(p.GetProperty("/api/scorer/matches/{matchId}/open-context").TryGetProperty("get",out _));var open=p.GetProperty("/api/scorer/matches/{matchId}/open").GetProperty("post");Assert.True(open.GetProperty("responses").TryGetProperty("201",out _));Assert.True(open.GetProperty("responses").TryGetProperty("200",out _));Assert.True(open.GetProperty("responses").TryGetProperty("409",out _));Assert.True(p.GetProperty("/api/scorer/matches/{matchId}/sheet").TryGetProperty("get",out _));}
 [Fact]public async Task Admin_readiness_and_oversight_share_opening_state_without_mutating_it(){var x=await Seed();var readiness=await factory.Client.GetFromJsonAsync<LigaVolley.Application.Matches.MatchReadinessDto>($"/api/admin/matches/{x.MatchId}/readiness",Json);Assert.True(readiness!.ReadyForScorer);Assert.Empty(readiness.Blockers);Assert.Contains(readiness.Warnings,w=>w.Code=="match_readiness_venue_missing");var before=await factory.Client.GetFromJsonAsync<LigaVolley.Application.Matches.AdminMatchSheetDto>($"/api/admin/matches/{x.MatchId}/match-sheet",Json);Assert.False(before!.Exists);await factory.Client.PostAsJsonAsync($"/api/scorer/matches/{x.MatchId}/open",Request(x),Json);var after=await factory.Client.GetFromJsonAsync<LigaVolley.Application.Matches.AdminMatchSheetDto>($"/api/admin/matches/{x.MatchId}/match-sheet",Json);Assert.True(after!.Exists);Assert.Equal(MatchSheetStatus.Open,after.Sheet!.Status);Assert.NotNull(after.Sheet.Session);var blocked=await factory.Client.GetFromJsonAsync<LigaVolley.Application.Matches.MatchReadinessDto>($"/api/admin/matches/{x.MatchId}/readiness",Json);Assert.False(blocked!.ReadyForScorer);Assert.Contains(blocked.Blockers,b=>b.Code=="match_readiness_match_sheet_already_exists");}
 [Fact]public async Task OpenApi_documents_admin_match_operations(){var json=await factory.Client.GetStringAsync("/swagger/v1/swagger.json");using var doc=JsonDocument.Parse(json);var p=doc.RootElement.GetProperty("paths");Assert.True(p.GetProperty("/api/admin/matches/{matchId}/readiness").TryGetProperty("get",out _));Assert.True(p.GetProperty("/api/admin/matches/{matchId}/match-sheet").TryGetProperty("get",out _));}
 private static OpenMatchSheetRequest Request(Data x)=>new(Guid.NewGuid(),"tablet-test",new(x.HomePlayers,x.HomePlayers[0],[],[]),new(x.AwayPlayers,x.AwayPlayers[0],[],[]));
 private async Task<Data> Seed(){await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<LigaVolleyDbContext>();var suffix=Guid.NewGuid().ToString("N")[..8];var hp=Enumerable.Range(0,6).Select(i=>new Player(new Person(null,null,$"H{i}",suffix,null,null,null,null))).ToArray();var ap=Enumerable.Range(0,6).Select(i=>new Player(new Person(null,null,$"A{i}",suffix,null,null,null,null))).ToArray();db.Players.AddRange(hp);db.Players.AddRange(ap);await db.SaveChangesAsync();var format=new CompetitionFormat($"MS{suffix}","Sheet",null,2,2);format.Phases.Add(new FormatPhase("R","Regular",PhaseType.RoundRobin,PhaseRole.Regular,1,1,FixtureMode.BalancedRandom));var competition=new Competition("Sheet",new Season((short)Random.Shared.Next(2100,30000),$"S{suffix}",null,null),new Division($"D{suffix}",(short)Random.Shared.Next(100,30000),Gender.Female),format,CompetitionPeriodType.Annual,null,null);var he=new TeamEntry(competition,new Team($"H{suffix}",Gender.Female,null),null);var ae=new TeamEntry(competition,new Team($"A{suffix}",Gender.Female,null),null);var hr=new CompetitionRoster(he);var ar=new CompetitionRoster(ae);for(var i=0;i<6;i++){hr.AddPlayer(hp[i],(short)(i+1),PlayerRole.Setter);ar.AddPlayer(ap[i],(short)(i+1),PlayerRole.Setter);}hr.Activate();ar.Activate();var match=new Match(competition,competition.Phases[0],null,he,ae,1,1);match.Schedule(DateTime.UtcNow.AddDays(1),null);var refs=Enumerable.Range(0,3).Select(i=>new Referee(new Person(null,null,$"O{i}",suffix,null,null,null,null))).ToArray();var mos=new[]{new MatchOfficial(match,refs[0],MatchOfficialRole.FirstReferee),new MatchOfficial(match,refs[1],MatchOfficialRole.SecondReferee),new MatchOfficial(match,refs[2],MatchOfficialRole.Scorer)};db.CompetitionRosters.AddRange(hr,ar);db.Matches.Add(match);db.MatchOfficials.AddRange(mos);await db.SaveChangesAsync();return new(match.MatchId,hr.Players.Select(p=>p.CompetitionRosterPlayerId).ToArray(),ar.Players.Select(p=>p.CompetitionRosterPlayerId).ToArray());}
 private sealed record Data(int MatchId,int[] HomePlayers,int[] AwayPlayers);
}
